def moduleDetails(moduleID, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0287000" if __import__("os").path.isdir("./environment_mix/0287000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        import uuid
        if prefix == "tfrq":
            return f"tfrq_{uuid.uuid4().hex[:26]}"
        return f"{prefix}_{uuid.uuid4().hex}"

    def _approx_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False).encode("utf-8"))
        except Exception:
            return None

    def _parse_z(dt_str):
        if not isinstance(dt_str, str) or not dt_str:
            return None
        try:
            if dt_str.endswith("Z"):
                return datetime.datetime.fromisoformat(dt_str[:-1])
            return datetime.datetime.fromisoformat(dt_str)
        except Exception:
            return None

    def _finalize_log(req_row, response_status, response_obj, module_row_id=None):
        req_row["response_status"] = response_status
        req_row["module_id"] = module_row_id
        req_row["latency_ms"] = int((time.time() - t0) * 1000)
        req_row["response_bytes"] = _approx_size(response_obj)
        req_row["updated_at"] = _now()
        reqs = _load("tool_requests.json") or []
        reqs.append(req_row)
        _save("tool_requests.json", reqs)

    def _rate_limited(tool_name, limit=120, window_s=60):
        reqs = _load("tool_requests.json") or []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        c = 0
        for r in reqs:
            if r.get("tool_name") != tool_name:
                continue
            dt = _parse_z(r.get("created_at"))
            if dt is None:
                continue
            if dt >= cutoff:
                c += 1
        return c >= limit

    req_params = {"moduleID": moduleID}
    req_row = {
        "id": _new_id("tfrq"),
        "tool_name": "moduleDetails",
        "request_params": req_params,
        "provider_id": None,
        "provider_doc_id": None,
        "module_id": None,
        "current_offset": None,
        "response_status": "invalid_request",
        "response_bytes": None,
        "latency_ms": None,
        "created_at": _now(),
        "updated_at": _now(),
    }

    if _rate_limited("moduleDetails"):
        resp = _err("RATE_LIMIT", "Rate limit exceeded")
        _finalize_log(req_row, "rate_limited", resp)
        return resp

    if moduleID is None or not isinstance(moduleID, str) or not moduleID.strip():
        resp = _err("VALIDATION_ERROR", "moduleID is required and must be a non-empty string")
        _finalize_log(req_row, "invalid_request", resp)
        return resp

    moduleID = moduleID.strip()

    mods = _load("modules.json") or []

    # Must locate by modules.module_id. But tolerate callers providing "namespace/name/provider" (no version)
    # by selecting the latest semver version present for that triple.
    def _semver_key(v):
        try:
            a, b, c = v.split(".")
            return (int(a), int(b), int(c))
        except Exception:
            return (-1, -1, -1)

    exact = None
    for m in mods:
        if m.get("module_id") == moduleID:
            exact = m
            break

    chosen = exact
    if chosen is None:
        parts = moduleID.split("/")
        if len(parts) == 3:
            ns, name, prov = parts
            cands = []
            for m in mods:
                if m.get("namespace") == ns and m.get("name") == name and m.get("provider") == prov:
                    cands.append(m)
            if cands:
                cands.sort(key=lambda r: _semver_key(r.get("version") or ""), reverse=True)
                chosen = cands[0]

    if chosen is None:
        resp = _err("NOT_FOUND", "moduleID not found", moduleID=moduleID)
        _finalize_log(req_row, "not_found", resp, module_row_id=None)
        return resp

    status = chosen.get("status")
    if status not in ("indexed", "stale"):
        resp = _err("NOT_FOUND", "module exists but is not available in cache for retrieval", moduleID=moduleID, status=status)
        _finalize_log(req_row, "not_found", resp, module_row_id=chosen.get("id"))
        return resp

    TTL_SECONDS = 24 * 3600
    should_refresh = False
    if status == "stale":
        should_refresh = True
    else:
        last = _parse_z(chosen.get("last_fetched_at"))
        if last is None:
            should_refresh = True
        else:
            age = (datetime.datetime.utcnow() - last).total_seconds()
            if age >= TTL_SECONDS:
                should_refresh = True

    # If stale, refresh and transition stale->indexed on success or stale->error on failure.
    if should_refresh and status == "stale":
        now = _now()
        if (chosen.get("documentation_markdown") is not None) or (chosen.get("inputs") is not None) or (chosen.get("outputs") is not None):
            chosen["status"] = "indexed"
            chosen["error_message"] = None
            chosen["last_fetched_at"] = now
            chosen["updated_at"] = now
        else:
            chosen["status"] = "error"
            chosen["error_message"] = chosen.get("error_message") or "Refresh failed: no cached module content to validate"
            chosen["last_fetched_at"] = chosen.get("last_fetched_at") or now
            chosen["updated_at"] = now

        for i, m in enumerate(mods):
            if m.get("id") == chosen.get("id"):
                mods[i] = chosen
                break
        _save("modules.json", mods)

    body = {
        "moduleID": chosen.get("module_id"),
        "id": chosen.get("id"),
        "namespace": chosen.get("namespace"),
        "name": chosen.get("name"),
        "provider": chosen.get("provider"),
        "version": chosen.get("version"),
        "description": chosen.get("description"),
        "verified": chosen.get("verified"),
        "downloads": chosen.get("downloads"),  # must not be mutated here
        "source_url": chosen.get("source_url"),
        "status": chosen.get("status"),
        "last_fetched_at": chosen.get("last_fetched_at"),
        "documentation_markdown": chosen.get("documentation_markdown"),
        "inputs": chosen.get("inputs"),
        "outputs": chosen.get("outputs"),
        "created_at": chosen.get("created_at"),
        "updated_at": chosen.get("updated_at"),
        "resolved_from": ("exact" if exact is not None else "latest_version_for_triple") if chosen else None,
        "requested_moduleID": moduleID,
    }

    _finalize_log(req_row, "ok", body, module_row_id=chosen.get("id"))
    return body

def resolveProviderDocID(providerName, providerNamespace, serviceSlug, providerDataType=None, providerVersion=None, **_extra):
    import json, os, datetime, time, re, difflib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0287000" if __import__("os").path.isdir("./environment_mix/0287000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        import uuid
        return f"{prefix}_{uuid.uuid4().hex}"

    def _approx_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False).encode("utf-8"))
        except Exception:
            return None

    def _log_request(tool_name, request_params, provider_id=None, provider_doc_id=None, module_id=None, current_offset=None, response_status="invalid_request", response_obj=None, latency_ms=None):
        reqs = _load("tool_requests.json")
        row = {
            "id": _new_id("tr"),
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "provider_id": provider_id,
            "provider_doc_id": provider_doc_id,
            "module_id": module_id,
            "current_offset": current_offset,
            "response_status": response_status,
            "response_bytes": _approx_size(response_obj) if response_obj is not None else None,
            "latency_ms": latency_ms,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("tool_requests.json", reqs)

    def _enforce_rate_limit(tool_name, max_per_minute=120):
        reqs = _load("tool_requests.json")
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        c = 0
        for r in reqs:
            if r.get("tool_name") != tool_name:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str) or not ts.endswith("Z"):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1])
            except Exception:
                continue
            if dt >= cutoff:
                c += 1
        return c < max_per_minute

    request_params = {
        "providerName": providerName,
        "providerNamespace": providerNamespace,
        "serviceSlug": serviceSlug,
    }
    if providerDataType is not None:
        request_params["providerDataType"] = providerDataType
    if providerVersion is not None:
        request_params["providerVersion"] = providerVersion

    if not _enforce_rate_limit("resolveProviderDocID"):
        resp = _err("RATE_LIMIT", "Rate limit exceeded for resolveProviderDocID")
        _log_request("resolveProviderDocID", request_params, response_status="rate_limited", response_obj=resp, latency_ms=int((time.time() - t0) * 1000))
        return resp

    # Validate required inputs
    for k, v in (("providerName", providerName), ("providerNamespace", providerNamespace), ("serviceSlug", serviceSlug)):
        if v is None or not isinstance(v, str) or v.strip() == "":
            resp = _err("VALIDATION_ERROR", f"{k} is required and must be a non-empty string")
            _log_request("resolveProviderDocID", request_params, response_status="invalid_request", response_obj=resp, latency_ms=int((time.time() - t0) * 1000))
            return resp

    if providerDataType is None:
        providerDataType = "resources"
    if not isinstance(providerDataType, str) or providerDataType not in ("resources", "data-sources", "functions", "guides", "overview"):
        resp = _err("VALIDATION_ERROR", "providerDataType must be one of: resources, data-sources, functions, guides, overview")
        _log_request("resolveProviderDocID", request_params, response_status="invalid_request", response_obj=resp, latency_ms=int((time.time() - t0) * 1000))
        return resp

    semver_re = re.compile(r"^\d+\.\d+\.\d+$")
    if providerVersion is not None:
        if not isinstance(providerVersion, str) or providerVersion.strip() == "":
            resp = _err("VALIDATION_ERROR", "providerVersion must be a non-empty string when provided")
            _log_request("resolveProviderDocID", request_params, response_status="invalid_request", response_obj=resp, latency_ms=int((time.time() - t0) * 1000))
            return resp
        if providerVersion != "latest" and not semver_re.match(providerVersion):
            resp = _err("VALIDATION_ERROR", "providerVersion must match x.y.z or be 'latest'")
            _log_request("resolveProviderDocID", request_params, response_status="invalid_request", response_obj=resp, latency_ms=int((time.time() - t0) * 1000))
            return resp

    providers = _load("providers.json")
    docs = _load("provider_docs.json")

    # resolve provider by exact match
    prov = None
    for p in providers:
        if not isinstance(p, dict):
            continue
        if p.get("namespace") == providerNamespace and p.get("name") == providerName:
            prov = p
            break

    if not prov:
        resp = {"candidates": []}
        _log_request("resolveProviderDocID", request_params, response_status="not_found", response_obj=resp, latency_ms=int((time.time() - t0) * 1000))
        return resp

    provider_id = prov.get("id")

    # Determine version: if omitted or 'latest', use providers.latest_version (may fetch upstream)
    resolved_version = providerVersion
    if resolved_version is None or resolved_version == "latest":
        lv = prov.get("latest_version")
        if isinstance(lv, str) and semver_re.match(lv):
            resolved_version = lv
        else:
            # Attempt to "fetch" from upstream: offline heuristic using max provider_docs.provider_version for this provider
            versions = []
            for d in docs:
                if not isinstance(d, dict):
                    continue
                if d.get("provider_id") != provider_id:
                    continue
                v = d.get("provider_version")
                if isinstance(v, str) and semver_re.match(v):
                    versions.append(v)
            def _ver_key(v):
                a, b, c = v.split(".")
                return (int(a), int(b), int(c))
            latest = None
            if versions:
                latest = sorted(set(versions), key=_ver_key)[-1]
            if latest is None:
                # cannot resolve latest
                resp = {"candidates": [], "provider": {"namespace": providerNamespace, "name": providerName, "version": None}}
                _log_request("resolveProviderDocID", request_params, provider_id=provider_id, response_status="not_found", response_obj=resp, latency_ms=int((time.time() - t0) * 1000))
                return resp
            # Persist providers.latest_version before continuing
            for i, p in enumerate(providers):
                if isinstance(p, dict) and p.get("id") == provider_id:
                    p["latest_version"] = latest
                    p["updated_at"] = now
                    providers[i] = p
                    prov = p
                    break
            _save("providers.json", providers)
            resolved_version = latest

    # Filter docs by provider_id, version, data type; enforce FK integrity
    providers_by_id = {p.get("id"): p for p in providers if isinstance(p, dict) and isinstance(p.get("id"), str)}
    pool = []
    for d in docs:
        if not isinstance(d, dict):
            continue
        if d.get("provider_id") != provider_id:
            continue
        if d.get("provider_id") not in providers_by_id:
            continue
        if d.get("provider_version") != resolved_version:
            continue
        if d.get("provider_data_type") != providerDataType:
            continue
        pool.append(d)

    # Rank by service_slug similarity to input serviceSlug
    target = serviceSlug.strip().lower()
    def _score(d):
        slug = (d.get("service_slug") or "").strip().lower()
        # difflib ratio plus exact/substring boosts
        ratio = difflib.SequenceMatcher(a=target, b=slug).ratio() if slug else 0.0
        boost = 0.0
        if slug == target:
            boost += 1.0
        elif target and slug and (target in slug or slug in target):
            boost += 0.25
        return ratio + boost

    ranked = sorted(pool, key=lambda d: (-_score(d), str(d.get("service_slug") or ""), str(d.get("canonical_path") or ""), str(d.get("id") or "")))

    # Return candidates (one or more); include minimal metadata and providerDocID mapping
    out = []
    seen = set()
    for d in ranked:
        ext = d.get("external_provider_doc_id")
        if not isinstance(ext, str) or ext in seen:
            continue
        seen.add(ext)
        out.append({
            "providerDocID": ext,
            "title": d.get("title"),
            "serviceSlug": d.get("service_slug"),
            "canonicalPath": d.get("canonical_path"),
            "dataType": d.get("provider_data_type"),
            "providerVersion": d.get("provider_version"),
            "status": d.get("status"),
        })

    resp = {
        "provider": {"namespace": providerNamespace, "name": providerName, "version": resolved_version},
        "candidates": out
    }

    # If no docs found, it's "not_found" per typical behavior
    final_status = "ok" if out else "not_found"

    # For successful resolutions, populate FK fields: provider_id always; provider_doc_id only if single best candidate
    provider_doc_id = None
    if out:
        # best candidate's internal id
        best_ext = out[0]["providerDocID"]
        for d in ranked:
            if d.get("external_provider_doc_id") == best_ext:
                provider_doc_id = d.get("id")
                break

    _log_request(
        "resolveProviderDocID",
        request_params,
        provider_id=provider_id,
        provider_doc_id=provider_doc_id,
        response_status=final_status,
        response_obj=resp,
        latency_ms=int((time.time() - t0) * 1000),
    )
    return resp

def searchModules(moduleQuery, currentOffset=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0287000" if __import__("os").path.isdir("./environment_mix/0287000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        import uuid
        return f"{prefix}_{uuid.uuid4().hex}"

    def _approx_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False).encode("utf-8"))
        except Exception:
            return None

    def _log_request(tool_name, request_params, provider_id=None, provider_doc_id=None, module_id=None, current_offset=None, response_status="invalid_request", response_obj=None, latency_ms=None):
        reqs = _load("tool_requests.json")
        row = {
            "id": _new_id("tr"),
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "provider_id": provider_id,
            "provider_doc_id": provider_doc_id,
            "module_id": module_id,
            "current_offset": current_offset,
            "response_status": response_status,
            "response_bytes": _approx_size(response_obj) if response_obj is not None else None,
            "latency_ms": latency_ms,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("tool_requests.json", reqs)

    def _enforce_rate_limit(tool_name, max_per_minute=120):
        reqs = _load("tool_requests.json")
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        c = 0
        for r in reqs:
            if r.get("tool_name") != tool_name:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str) or not ts.endswith("Z"):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1])
            except Exception:
                continue
            if dt >= cutoff:
                c += 1
        return c < max_per_minute

    if currentOffset is None:
        currentOffset = 0

    request_params = {"moduleQuery": moduleQuery, "currentOffset": currentOffset}

    if not _enforce_rate_limit("searchModules"):
        resp = _err("RATE_LIMIT", "Rate limit exceeded for searchModules")
        _log_request("searchModules", request_params, current_offset=currentOffset, response_status="rate_limited", response_obj=resp, latency_ms=int((time.time() - t0) * 1000))
        return resp

    if moduleQuery is None or not isinstance(moduleQuery, str) or moduleQuery.strip() == "":
        resp = _err("VALIDATION_ERROR", "moduleQuery is required and must be a non-empty string")
        _log_request("searchModules", request_params, current_offset=currentOffset, response_status="invalid_request", response_obj=resp, latency_ms=int((time.time() - t0) * 1000))
        return resp

    # currentOffset must be treated as integer offset >= 0
    if isinstance(currentOffset, bool):
        resp = _err("VALIDATION_ERROR", "currentOffset must be a number >= 0")
        _log_request("searchModules", request_params, current_offset=currentOffset, response_status="invalid_request", response_obj=resp, latency_ms=int((time.time() - t0) * 1000))
        return resp
    if not isinstance(currentOffset, (int, float)):
        resp = _err("VALIDATION_ERROR", "currentOffset must be a number >= 0")
        _log_request("searchModules", request_params, current_offset=currentOffset, response_status="invalid_request", response_obj=resp, latency_ms=int((time.time() - t0) * 1000))
        return resp
    if currentOffset < 0:
        resp = _err("VALIDATION_ERROR", "currentOffset must be >= 0")
        _log_request("searchModules", request_params, current_offset=currentOffset, response_status="invalid_request", response_obj=resp, latency_ms=int((time.time() - t0) * 1000))
        return resp
    offset = int(currentOffset)

    modules = _load("modules.json")
    q = moduleQuery.strip().lower()

    def _text(m):
        parts = [
            m.get("namespace"),
            m.get("name"),
            m.get("description"),
        ]
        return " ".join([p for p in parts if isinstance(p, str)]).lower()

    matched = []
    for m in modules:
        if not isinstance(m, dict):
            continue
        if q in _text(m):
            matched.append(m)

    # Sort (verified desc, downloads desc, name asc)
    def _sort_key(m):
        verified = 1 if m.get("verified") is True else 0
        downloads = m.get("downloads")
        if not isinstance(downloads, int):
            downloads = -1
        name = m.get("name")
        if not isinstance(name, str):
            name = ""
        return (-verified, -downloads, name.lower(), str(m.get("module_id") or ""))

    matched.sort(key=_sort_key)

    # Maximum page size (implementation-defined)
    PAGE_SIZE = 25

    # Slice with offset; ensure no duplicate module_id within response
    page = matched[offset: offset + PAGE_SIZE]
    results = []
    seen_module_ids = set()
    for m in page:
        mid = m.get("module_id")
        if not isinstance(mid, str) or mid in seen_module_ids:
            continue
        seen_module_ids.add(mid)
        results.append({
            "moduleID": mid,
            "namespace": m.get("namespace"),
            "name": m.get("name"),
            "provider": m.get("provider"),
            "version": m.get("version"),
            "description": m.get("description"),
            "verified": m.get("verified"),
        })

    total = len(matched)
    has_more = (offset + PAGE_SIZE) < total
    next_offset = (offset + PAGE_SIZE) if has_more else None

    resp = {
        "modules": results,
        "pagination": {
            "total": total,
            "currentOffset": offset,
            "pageSize": PAGE_SIZE,
            "hasMore": has_more,
            "nextOffset": next_offset,
        }
    }

    final_status = "ok" if total > 0 else "not_found"

    # For analytics FK: if exactly one result, attach module_id; otherwise null
    module_fk = None
    if len(results) == 1:
        only_mid = results[0]["moduleID"]
        for m in matched:
            if m.get("module_id") == only_mid:
                module_fk = m.get("id")
                break

    _log_request(
        "searchModules",
        request_params,
        module_id=module_fk,
        current_offset=offset,
        response_status=final_status,
        response_obj=resp,
        latency_ms=int((time.time() - t0) * 1000),
    )
    return resp

