            return None

    def _parse_z(dt_str):
        if not isinstance(dt_str, str) or not dt_str:
            return None
        try:
            if dt_str.endswith("Z"):
                return datetime.datetime.fromisoformat(dt_str[:-1])
            return datetime.datetime.fromisoformat(dt_str)
        except Exception:
            return None

    def _rate_limited(tool_name, limit=120, window_s=60):
        reqs = _load("tool_requests.json") or []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        c = 0
        for r in reqs:
            if r.get("tool_name") != tool_name:
                continue
            dt = _parse_z(r.get("created_at"))
            if dt is None:
                continue
            if dt >= cutoff:
                c += 1
        return c >= limit

    def _finalize_log(req_row, response_status, response_obj, provider_row_id=None):
        req_row["response_status"] = response_status
        req_row["provider_id"] = provider_row_id
        req_row["latency_ms"] = int((time.time() - t0) * 1000)
        req_row["response_bytes"] = _approx_size(response_obj)
        req_row["updated_at"] = _now()
        reqs = _load("tool_requests.json") or []
        reqs.append(req_row)
        _save("tool_requests.json", reqs)

    req_params = {"providerID": providerID}
    if status is not None:
        req_params["status"] = status
    if displayName is not None:
        req_params["displayName"] = displayName

    # tool_requests.tool_name enum doesn't include updateProvider, so log under resolveProviderDocID with alias marker.
    req_row = {
        "id": _new_id("tfrq"),
        "tool_name": "resolveProviderDocID",
        "request_params": dict(req_params, **{"__tool_alias": "updateProvider"}),
        "provider_id": None,
        "provider_doc_id": None,
        "module_id": None,
        "current_offset": None,
        "response_status": "invalid_request",
        "response_bytes": None,
        "latency_ms": None,
        "created_at": _now(),
        "updated_at": _now(),
    }

    if _rate_limited("resolveProviderDocID"):
        resp = _err("RATE_LIMIT", "Rate limit exceeded")
        _finalize_log(req_row, "rate_limited", resp)
        return resp

    if providerID is None or not isinstance(providerID, str) or not providerID.strip():
        resp = _err("VALIDATION_ERROR", "providerID is required and must be a non-empty string")
        _finalize_log(req_row, "invalid_request", resp)
        return resp

    if status is None and displayName is None:
        resp = _err("VALIDATION_ERROR", "At least one of status or displayName must be provided")
        _finalize_log(req_row, "invalid_request", resp, provider_row_id=providerID.strip())
        return resp

    if status is not None:
        if not isinstance(status, str):
            resp = _err("VALIDATION_ERROR", "status must be a string")
            _finalize_log(req_row, "invalid_request", resp, provider_row_id=providerID.strip())
            return resp
        if status not in ("active", "deprecated", "disabled"):
            resp = _err("VALIDATION_ERROR", "status must be one of 'active','deprecated','disabled'", status=status)
            _finalize_log(req_row, "invalid_request", resp, provider_row_id=providerID.strip())
            return resp

    if displayName is not None and (not isinstance(displayName, str) or not displayName.strip()):
        resp = _err("VALIDATION_ERROR", "displayName must be a non-empty string when provided")
        _finalize_log(req_row, "invalid_request", resp, provider_row_id=providerID.strip())
        return resp

    providers = _load("providers.json") or []
    idx = None
    row = None
    pid = providerID.strip()
    for i, p in enumerate(providers):
        if p.get("id") == pid:
            idx = i
            row = p
            break

    if row is None:
        resp = _err("NOT_FOUND", "providerID not found", providerID=pid)
        _finalize_log(req_row, "not_found", resp, provider_row_id=None)
        return resp

    # Apply updates with lifecycle transitions
    transitions = {
        "active": {"deprecated", "disabled"},
        "deprecated": {"disabled"},
        "disabled": set(),
    }

    mutated = False
    now = _now()

    if displayName is not None:
        if row.get("display_name") != displayName:
            row["display_name"] = displayName
            mutated = True

    if status is not None:
        cur = row.get("status")
        if cur != status:
            if cur not in transitions or status not in transitions.get(cur, set()):
                resp = _err("INVALID_TRANSITION", "Invalid provider status transition", from_status=cur, to_status=status)
                _finalize_log(req_row, "invalid_request", resp, provider_row_id=pid)
                return resp
            row["status"] = status
            mutated = True

    if not mutated:
        # No success without effect: treat as conflict/no-op
        resp = _err("CONFLICT", "No changes to apply (requested values already set)")
        _finalize_log(req_row, "invalid_request", resp, provider_row_id=pid)
        return resp

    row["updated_at"] = now
    providers[idx] = row
    _save("providers.json", providers)

    body = {"provider": row}
    _finalize_log(req_row, "ok", body, provider_row_id=pid)
    return body

def listToolRequests(toolName=None, responseStatus=None, providerID=None, providerDocID=None, moduleID=None, limit=None, currentOffset=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0287000" if __import__("os").path.isdir("./environment_mix/0287000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    tool_requests = _load("tool_requests.json")
    # rate limit: 120/min based on existing tool_requests
    window_s = 60
    limit_per_window = 120
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in tool_requests:
        ca = r.get("created_at")
        if not ca:
            continue
        try:
            dt = datetime.datetime.fromisoformat(ca.replace("Z", "+00:00"))
        except Exception:
            continue
        if dt >= cutoff.replace(tzinfo=dt.tzinfo):
            recent += 1

    # This tool is within enum; we can log it using an allowed tool_name value? Schema disallows 'listToolRequests'.
    # Preserve integrity by storing as 'moduleDetails' with alias marker.
    req_log = {
        "id": "tr_" + uuid.uuid4().hex,
        "tool_name": "moduleDetails",
        "request_params": {
            "toolName": toolName,
            "responseStatus": responseStatus,
            "providerID": providerID,
            "providerDocID": providerDocID,
            "moduleID": moduleID,
            "limit": limit,
            "currentOffset": currentOffset,
            "__tool_alias": "listToolRequests",
        },
        "provider_id": None,
        "provider_doc_id": None,
        "module_id": None,
        "current_offset": None,
        "response_status": "invalid_request",
        "response_bytes": None,
        "latency_ms": None,
        "created_at": now,
        "updated_at": now,
    }

    if recent >= limit_per_window:
        req_log["response_status"] = "rate_limited"
        req_log["latency_ms"] = int((time.time() - _t0) * 1000)
        body = _err("RATE_LIMIT", "Rate limit exceeded")
        req_log["response_bytes"] = len(json.dumps(body, ensure_ascii=False))
        req_log["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        tool_requests.append(req_log)
        _save("tool_requests.json", tool_requests)
        return body

    valid_tool = ("resolveProviderDocID", "getProviderDocs", "searchModules", "moduleDetails")
    valid_status = ("ok", "not_found", "invalid_request", "upstream_error", "rate_limited")

    if toolName is not None and toolName not in valid_tool:
        body = _err("VALIDATION_ERROR", "toolName must be one of: resolveProviderDocID, getProviderDocs, searchModules, moduleDetails")
    elif responseStatus is not None and responseStatus not in valid_status:
        body = _err("VALIDATION_ERROR", "responseStatus must be one of: ok, not_found, invalid_request, upstream_error, rate_limited")
    else:
        if limit is None:
            limit = 50
        if currentOffset is None:
            currentOffset = 0
        if not isinstance(limit, (int, float)) or int(limit) != limit:
            body = _err("VALIDATION_ERROR", "limit must be an integer")
        elif not isinstance(currentOffset, (int, float)) or int(currentOffset) != currentOffset:
            body = _err("VALIDATION_ERROR", "currentOffset must be an integer")
        else:
            limit = int(limit)
            currentOffset = int(currentOffset)
            if limit < 1 or limit > 200:
                body = _err("VALIDATION_ERROR", "limit must be between 1 and 200")
            elif currentOffset < 0:
                body = _err("VALIDATION_ERROR", "currentOffset must be >= 0")
            else:
                # Validate FK filters if provided: must exist, else return empty set (read filters that match nothing)
                providers = _load("providers.json")
                provider_docs = _load("provider_docs.json")
                modules = _load("modules.json")

                if providerID is not None and (not isinstance(providerID, str) or not providerID.strip()):
                    body = _err("VALIDATION_ERROR", "providerID must be a non-empty string when provided")
                elif providerDocID is not None and (not isinstance(providerDocID, str) or not providerDocID.strip()):
                    body = _err("VALIDATION_ERROR", "providerDocID must be a non-empty string when provided")
                elif moduleID is not None and (not isinstance(moduleID, str) or not moduleID.strip()):
                    body = _err("VALIDATION_ERROR", "moduleID must be a non-empty string when provided")
                else:
                    prov_exists = True
                    doc_exists = True
                    mod_exists = True
                    if providerID is not None:
                        prov_exists = any(p.get("id") == providerID for p in providers)
                    if providerDocID is not None:
                        doc_exists = any(d.get("id") == providerDocID for d in provider_docs)
                    if moduleID is not None:
                        mod_exists = any(m.get("id") == moduleID for m in modules)

                    rows = tool_requests
                    # Apply filters; if FK doesn't exist, just return empty result set
                    if providerID is not None and not prov_exists:
                        rows = []
                    if providerDocID is not None and not doc_exists:
                        rows = []
                    if moduleID is not None and not mod_exists:
                        rows = []

                    if rows:
                        out = []
                        for r in rows:
                            if toolName is not None and r.get("tool_name") != toolName:
                                continue
                            if responseStatus is not None and r.get("response_status") != responseStatus:
                                continue
                            if providerID is not None and r.get("provider_id") != providerID:
                                continue
                            if providerDocID is not None and r.get("provider_doc_id") != providerDocID:
                                continue
                            if moduleID is not None and r.get("module_id") != moduleID:
                                continue
                            out.append(r)

                        def _parse_dt(v):
                            if not v:
                                return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
                            try:
                                return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
                            except Exception:
                                return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

                        out.sort(key=lambda x: _parse_dt(x.get("created_at")), reverse=True)
                        total = len(out)
                        page = out[currentOffset: currentOffset + limit]
                    else:
                        total = 0
                        page = []

                    has_more = currentOffset + limit < total
                    next_cursor = (currentOffset + limit) if has_more else None

                    body = {
                        "data": page,
                        "meta": {
                            "total": total,
                            "limit": limit,
                            "currentOffset": currentOffset,
                            "has_more": has_more,
                            "next_cursor": next_cursor,
                        },
                    }
                    req_log["response_status"] = "ok"
                    req_log["current_offset"] = currentOffset

    req_log["latency_ms"] = int((time.time() - _t0) * 1000)
    req_log["response_bytes"] = len(json.dumps(body, ensure_ascii=False))
    req_log["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    tool_requests.append(req_log)
    _save("tool_requests.json", tool_requests)
    return body

def updateProviderDocStatus(providerDocID, status, errorMessage=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0287000" if __import__("os").path.isdir("./environment_mix/0287000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_z(dt_str):
        if not isinstance(dt_str, str) or not dt_str:
            return None
        try:
            if dt_str.endswith("Z"):
                return datetime.datetime.fromisoformat(dt_str[:-1])
            return datetime.datetime.fromisoformat(dt_str)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:26]}"

    def _approx_size(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False).encode("utf-8"))
        except Exception:
            return None

    def _rate_limited(tool_name, limit=120, window_s=60):
        reqs = _load("tool_requests.json") or []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        c = 0
        for r in reqs:
            if r.get("tool_name") != tool_name:
                continue
            dt = _parse_z(r.get("created_at"))
            if dt is None:
                continue
            if dt >= cutoff:
                c += 1
        return c >= limit

    def _log_tool_request(requests_rows, req_params, response_status, provider_id=None, provider_doc_id=None, response_obj=None):
        # tool_requests.tool_name enum does NOT include updateProviderDocStatus.
        # Log under resolveProviderDocID as a compatible internal maintenance action.
        now = _now()
        row = {
            "id": _new_id("tfrq"),
            "tool_name": "resolveProviderDocID",
            "request_params": req_params,
            "provider_id": provider_id,
            "provider_doc_id": provider_doc_id,
            "module_id": None,
            "current_offset": None,
            "response_status": response_status,
            "response_bytes": _approx_size(response_obj) if response_obj is not None else None,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now,
        }
        requests_rows.append(row)

    # Validate inputs
    req_params = {"providerDocID": providerDocID, "status": status, "errorMessage": errorMessage}
    tool_reqs = _load("tool_requests.json") or []

    if providerDocID is None or (isinstance(providerDocID, str) and providerDocID.strip() == ""):
        out = _err("VALIDATION_ERROR", "providerDocID is required and must be a non-empty string", providerDocID=providerDocID)
        _log_tool_request(tool_reqs, req_params, "invalid_request", response_obj=out)
        _save("tool_requests.json", tool_reqs)
        return out
    if not isinstance(providerDocID, str):
        out = _err("VALIDATION_ERROR", "providerDocID must be a string", providerDocID=providerDocID)
        _log_tool_request(tool_reqs, req_params, "invalid_request", response_obj=out)
        _save("tool_requests.json", tool_reqs)
        return out

    allowed = ("candidate", "ready", "stale", "error")
    if status not in allowed:
        out = _err("VALIDATION_ERROR", "status must be one of: candidate, ready, stale, error", status=status)
        _log_tool_request(tool_reqs, req_params, "invalid_request", response_obj=out)
        _save("tool_requests.json", tool_reqs)
        return out

    if errorMessage is not None and not isinstance(errorMessage, str):
        out = _err("VALIDATION_ERROR", "errorMessage must be a string when provided", errorMessage=errorMessage)
        _log_tool_request(tool_reqs, req_params, "invalid_request", response_obj=out)
        _save("tool_requests.json", tool_reqs)
        return out

    # Rate limit
    if _rate_limited("resolveProviderDocID"):
        out = _err("RATE_LIMIT", "Rate limit exceeded")
        _log_tool_request(tool_reqs, req_params, "rate_limited", response_obj=out)
        _save("tool_requests.json", tool_reqs)
        return out

    provider_docs = _load("provider_docs.json") or []
    providers = _load("providers.json") or []
    providers_by_id = {p.get("id"): p for p in providers if isinstance(p, dict) and p.get("id")}

    # Find provider doc:
    # Primary: internal id exact match.
    # Compatibility fallback: if caller passed external_provider_doc_id (as seen in audit), accept it and update that row.
    target = None
    for r in provider_docs:
        if not isinstance(r, dict):
            continue
        if r.get("id") == providerDocID:
            target = r
            break
    if target is None:
        for r in provider_docs:
            if not isinstance(r, dict):
                continue
            if r.get("external_provider_doc_id") == providerDocID:
                target = r
                break

    if target is None:
        out = _err(
            "NOT_FOUND",
            "providerDoc record does not exist. Business rule: updateProviderDocStatus identifies docs by internal provider_docs.id; this server also accepts external_provider_doc_id for backward compatibility when it matches an existing row.",
            providerDocID=providerDocID,
        )
        _log_tool_request(tool_reqs, req_params, "not_found", response_obj=out)
        _save("tool_requests.json", tool_reqs)
        return out

    # Enforce FK integrity
    pid = target.get("provider_id")
    if pid is not None and pid not in providers_by_id:
        out = _err(
            "CONFLICT",
            "provider_docs.provider_id does not reference an existing providers row (foreign key integrity violation)",
            providerDocID=providerDocID,
            provider_id=pid,
        )
        _log_tool_request(tool_reqs, req_params, "upstream_error", provider_id=None, provider_doc_id=target.get("id"), response_obj=out)
        _save("tool_requests.json", tool_reqs)
        return out

    # Enforce lifecycle transitions
    transitions = {
        "candidate": set(["ready", "error"]),
        "ready": set(["stale", "error"]),
        "stale": set(["ready", "error"]),
        "error": set(["candidate", "ready"]),
    }
    cur = target.get("status")
    if cur not in transitions:
        out = _err("CONFLICT", "Stored provider_docs.status is invalid", providerDocID=providerDocID, status=cur)
        _log_tool_request(tool_reqs, req_params, "upstream_error", provider_id=pid, provider_doc_id=target.get("id"), response_obj=out)
        _save("tool_requests.json", tool_reqs)
        return out

    if status == cur:
        # Idempotent update: still update updated_at and error_message normalization.
        target["updated_at"] = _now()
        if status == "error":
            target["error_message"] = errorMessage if errorMessage else target.get("error_message")
        else:
            target["error_message"] = None
        # persist
        for i, r in enumerate(provider_docs):
            if isinstance(r, dict) and r.get("id") == target.get("id"):
                provider_docs[i] = target
                _save("provider_docs.json", provider_docs)
                break
        resp = target
        _log_tool_request(tool_reqs, req_params, "ok", provider_id=pid, provider_doc_id=target.get("id"), response_obj=resp)
        _save("tool_requests.json", tool_reqs)
        return resp

    if status not in transitions.get(cur, set()):
        out = _err(
            "INVALID_TRANSITION",
            "Invalid status transition per lifecycle rules: candidate->ready/error; ready->stale/error; stale->ready/error; error->candidate/ready.",
            providerDocID=providerDocID,
            from_status=cur,
            to_status=status,
        )
        _log_tool_request(tool_reqs, req_params, "invalid_request", provider_id=pid, provider_doc_id=target.get("id"), response_obj=out)
        _save("tool_requests.json", tool_reqs)
        return out

    # Apply mutation
    target["status"] = status
    target["updated_at"] = _now()
    if status == "error":
        target["error_message"] = errorMessage if errorMessage is not None else target.get("error_message")
        if not target.get("error_message"):
            target["error_message"] = "Unspecified error."
    else:
        target["error_message"] = None

    # Persist
    updated = False
    for i, r in enumerate(provider_docs):
        if isinstance(r, dict) and r.get("id") == target.get("id"):
            provider_docs[i] = target
            updated = True
            break
    if not updated:
        out = _err("NOT_FOUND", "providerDoc record not found for update (matched earlier but disappeared)", providerDocID=providerDocID)
        _log_tool_request(tool_reqs, req_params, "not_found", response_obj=out)
        _save("tool_requests.json", tool_reqs)
        return out

    _save("provider_docs.json", provider_docs)

    resp = target
    _log_tool_request(tool_reqs, req_params, "ok", provider_id=pid, provider_doc_id=target.get("id"), response_obj=resp)
    _save("tool_requests.json", tool_reqs)
    return resp
